import styled from 'styled-components';

import {
  InstrumentEffects,
  LIVE_INPUT_EFFECTS_KEY,
  effectDefinitions,
  effectNames,
  maxEffectsVolume,
} from 'app/services/EffectsService/settings';

import { EffectPresets } from './EffectPresets';
import { WahControl } from './WahControl';

export const LiveInputEffects = ({
  settings,
  onChange,
}: {
  settings: InstrumentEffects;
  onChange: (settings: InstrumentEffects) => void;
}) => (
  <Controls>
    <EffectPresets settings={settings} onChange={onChange} />
    <label>
      Громкость выхода: {settings.volume}%
      <input
        type="range"
        aria-label="Громкость живого выхода"
        min={0}
        max={maxEffectsVolume(LIVE_INPUT_EFFECTS_KEY)}
        step={1}
        value={settings.volume}
        onChange={event =>
          onChange({ ...settings, volume: Number(event.target.value) })
        }
      />
    </label>
    <details>
      <summary>Настроить эффекты входа</summary>
      <Bypass>
        <input
          type="checkbox"
          checked={settings.bypass}
          onChange={event =>
            onChange({ ...settings, bypass: event.target.checked })
          }
        />
        Обход эффектов входа
      </Bypass>
      <Pedals>
        {effectNames.map(name => {
          const definition = effectDefinitions[name];
          const effect = settings[name];
          const update = (key: string, value: number | boolean) =>
            onChange({ ...settings, [name]: { ...effect, [key]: value } });
          return (
            <fieldset key={name}>
              <legend>
                <Bypass>
                  <input
                    type="checkbox"
                    checked={effect.enabled}
                    onChange={event => update('enabled', event.target.checked)}
                  />
                  {definition.title}
                </Bypass>
              </legend>
              {name === 'wah' && (
                <WahControl settings={settings} onChange={onChange} />
              )}
              {name === 'compressor' && (
                <p>
                  Добавляет около 6 мс задержки. Для минимальной задержки
                  оставьте выключенным.
                </p>
              )}
              {definition.controls.map(control => (
                <label key={control.key}>
                  {control.label}:{' '}
                  {(effect as unknown as Record<string, number>)[control.key]}{' '}
                  {control.unit}
                  <input
                    type="range"
                    aria-label={`Вход: ${control.label}`}
                    min={control.min}
                    max={control.max}
                    step={control.step}
                    disabled={!effect.enabled || settings.bypass}
                    value={
                      (effect as unknown as Record<string, number>)[control.key]
                    }
                    onChange={event =>
                      update(control.key, Number(event.target.value))
                    }
                  />
                </label>
              ))}
            </fieldset>
          );
        })}
      </Pedals>
    </details>
  </Controls>
);

const Controls = styled.div`
  margin: 16px 0;
  padding: 12px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 8px;
  label {
    margin-top: 10px;
  }
  input[type='range'] {
    width: 100%;
  }
  summary {
    margin-top: 12px;
    cursor: pointer;
  }
`;
const Bypass = styled.label`
  display: inline-flex !important;
  flex-direction: row !important;
  align-items: center;
  gap: 6px;
`;
const Pedals = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(230px, 100%), 1fr));
  gap: 12px;
  margin-top: 12px;
  fieldset {
    min-width: 0;
    border: 1px solid ${p => p.theme.border};
    border-radius: 6px;
  }
`;
