import { useSelector } from 'react-redux';
import styled from 'styled-components';

import {
  KeyCode,
  keyboardButtons,
  selectKeyboard,
} from 'app/services/KeyboardService';
import { selectSettings } from 'app/services/SettingsService';

import { KeyboardKey } from './KeyboardKey';

export const Keyboard = ({ keyboardWarning }) => {
  const { pressedKeys } = useSelector(selectKeyboard);
  const { applicature } = useSelector(selectSettings);
  const keys = Object.keys(keyboardButtons) as KeyCode[];

  return (
    <KeyboardWrapper>
      {keyboardWarning ? (
        <KeyboardWarning>(!) {keyboardWarning}</KeyboardWarning>
      ) : null}

      {keys.map(code => (
        <KeyboardKey
          key={code}
          code={code}
          isPressed={pressedKeys.includes(code)}
          isHighlighted={applicature.includes(code)}
        />
      ))}
    </KeyboardWrapper>
  );
};

const KeyboardWrapper = styled.div`
  position: relative;
  user-select: none;
`;

const KeyboardWarning = styled.div`
  background-color: ${p => p.theme.warningBackground};
  color: ${p => p.theme.warning};
  position: relative;
  top: -30px;
  left: -50px;
`;
