import { useEffect, useState } from 'react';

import { muteNote, playNote } from 'app/services/SynthesizerService';

import {
  MetronomeRhythm,
  MetronomeTimeSignature,
  createMetronomePattern,
} from './rhythm';

const clickNotes = ['D4', 'D#4', 'F#4'] as const;
const stopClicks = () => clickNotes.forEach(note => muteNote('drums', note));

export const useMetronome = (
  active: boolean,
  bpm: number,
  meter: MetronomeTimeSignature,
  rhythm: MetronomeRhythm,
) => {
  const [beat, setBeat] = useState<number | null>(null);

  useEffect(() => {
    setBeat(null);
    if (!active) return;

    const { events, beatDuration, duration } = createMetronomePattern(
      meter,
      rhythm,
      bpm,
    );
    let index = 0;
    let deadline = performance.now() + beatDuration;
    let timer: number;
    const tick = () => {
      const now = performance.now();
      // Browsers throttle background tabs. Restart rather than replaying
      // missed beats in a burst when the page becomes responsive again.
      if (now - deadline >= beatDuration) {
        index = 0;
        deadline = now;
      }
      const event = events[index];
      stopClicks();
      playNote(
        'drums',
        event.accent ? 'D4' : event.subdivision === 0 ? 'D#4' : 'F#4',
      );
      setBeat(event.beat);
      index = (index + 1) % events.length;
      const nextOffset = index === 0 ? duration : events[index].offset;
      deadline += nextOffset - event.offset;
      timer = window.setTimeout(
        tick,
        Math.max(0, deadline - performance.now()),
      );
    };
    timer = window.setTimeout(tick, beatDuration);

    return () => {
      window.clearTimeout(timer);
      stopClicks();
    };
  }, [active, bpm, meter, rhythm]);

  return active ? beat : null;
};
