import { makeExpression } from 'app/services/MelodiesService/expression';
import { getNoteDuration } from 'app/services/MelodiesService/timing';
import type { NoteInMelody } from 'app/services/MelodiesService/types';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import type { Note } from 'app/services/NotesService/types';
import { detectPitch } from 'app/services/TunerService/pitch';

import type { GuitarTake } from './capture';

type Frame = { time: number; midi: number; level: number };
const midiFor = (note: Note) =>
  (Number(note.slice(-1)) + 1) * 12 +
  chromaticNotes.indexOf(note.slice(0, -1) as typeof chromaticNotes[number]);

/** Refine isolated, continuous voices after capture. Chords and uncertain
 * transitions keep the original transcription. This never changes raw PCM. */
export const recognizeGuitarExpression = async (
  take: GuitarTake,
  notes: NoteInMelody[],
  signal?: AbortSignal,
): Promise<NoteInMelody[]> => {
  if (!notes.length || take.samples.length < take.sampleRate * 0.18)
    return notes;
  const rate = take.sampleRate;
  const size = Math.round(rate * 0.04);
  const hop = Math.round(rate * 0.02);
  const takeEnd = (take.samples.length / rate) * 1000;
  const runs: Frame[][] = [];
  let run: Frame[] = [];
  let previousLevel = 0;
  for (
    let start = 0, index = 0;
    start + size <= take.samples.length;
    start += hop, index++
  ) {
    if (signal?.aborted) throw new DOMException('Cancelled', 'AbortError');
    if (index && index % 128 === 0)
      await new Promise(resolve => setTimeout(resolve, 0));
    const samples = take.samples.subarray(start, start + size);
    const frequency = detectPitch(samples, rate, 2000);
    let energy = 0;
    samples.forEach(value => {
      energy += value * value;
    });
    const level = Math.sqrt(energy / size);
    const time = (start / rate) * 1000;
    const midi = frequency ? 69 + 12 * Math.log2(frequency / 440) : NaN;
    const last = run[run.length - 1];
    const attack =
      last &&
      time - run[0].time >= 160 &&
      level > Math.max(0.015, previousLevel * 1.65);
    if (!frequency || (last && (Math.abs(last.midi - midi) > 0.85 || attack))) {
      if (run.length) runs.push(run);
      run = [];
    }
    if (frequency) run.push({ time, midi, level });
    previousLevel = level;
  }
  if (run.length) runs.push(run);
  const removed = new Set<NoteInMelody>();
  const expressive: NoteInMelody[] = [];
  runs.forEach(frames => {
    const first = frames[0];
    const last = frames[frames.length - 1];
    if (last.time - first.time < 180) return;
    const begin = first.time;
    const end = Math.min(takeEnd, last.time + 40);
    const covered = notes.filter(
      note =>
        !removed.has(note) &&
        note.start < end - 20 &&
        note.start + getNoteDuration(note) > begin + 20,
    );
    if (
      !covered.length ||
      covered.some(
        note =>
          note.start < begin - 80 ||
          note.start + getNoteDuration(note) > end + 80,
      )
    )
      return;
    // Two established simultaneous voices cannot be assigned one pitch curve.
    if (
      covered.some((note, i) =>
        covered
          .slice(i + 1)
          .some(
            other =>
              Math.min(
                note.start + getNoteDuration(note),
                other.start + getNoteDuration(other),
              ) -
                Math.max(note.start, other.start) >
              60,
          ),
      )
    )
      return;
    const root = Math.round(first.midi);
    if (
      root < 12 ||
      root > 119 ||
      covered.some(note => Math.abs(midiFor(note.note) - root) > 12)
    )
      return;
    const start = Math.max(
      0,
      Math.min(begin, ...covered.map(note => note.start)),
    );
    const stop = Math.min(
      takeEnd,
      Math.max(end, ...covered.map(note => note.start + getNoteDuration(note))),
    );
    const expression = makeExpression(
      frames.map(frame => ({
        position: (frame.time - start) / (stop - start),
        cents: (frame.midi - root) * 100,
      })),
    );
    if (!expression?.techniques.length) return;
    // A fixed detuning is tuning error, not evidence of a playing gesture.
    const cents = expression.points.map(point => point.cents);
    if (Math.max(...cents) - Math.min(...cents) < 40) return;
    covered.forEach(note => removed.add(note));
    expressive.push({
      note: `${chromaticNotes[root % 12]}${Math.floor(root / 12) - 1}` as Note,
      start,
      duration: stop - start,
      expression,
    });
  });
  return [...notes.filter(note => !removed.has(note)), ...expressive].sort(
    (a, b) => a.start - b.start,
  );
};
