import { useCallback, useEffect, useRef, useState } from 'react';

import { TunerCapture, openTunerCapture } from './capture';
import { centsBetween, detectPitch } from './pitch';

const errorMessage = (cause: unknown) => {
  const name = cause instanceof Error ? cause.name : '';
  if (name === 'NotAllowedError' || name === 'SecurityError')
    return 'Разрешите доступ к микрофону в настройках сайта и попробуйте снова.';
  if (name === 'NotFoundError' || name === 'OverconstrainedError')
    return 'Аудиовход не найден. Подключите микрофон или аудиоинтерфейс и выберите его снова.';
  if (name === 'NotReadableError')
    return 'Не удалось открыть аудиовход. Проверьте устройство и другие аудиоприложения.';
  return 'Аудиовход отключён или недоступен. Проверьте подключение и попробуйте снова.';
};

export const useTuner = () => {
  const [status, setStatus] = useState<'idle' | 'connecting' | 'listening'>(
    'idle',
  );
  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]);
  const [deviceId, setDeviceId] = useState('');
  const [channel, setChannel] = useState(0);
  const [channels, setChannels] = useState(1);
  const [frequency, setFrequency] = useState<number | null>(null);
  const [level, setLevel] = useState(0);
  const [clipping, setClipping] = useState(false);
  const [error, setError] = useState('');
  const capture = useRef<TunerCapture>();
  const request = useRef<AbortController>();
  const history = useRef<number[]>([]);
  const supported =
    typeof navigator.mediaDevices?.getUserMedia === 'function' &&
    typeof (window.AudioContext || (window as any).webkitAudioContext) ===
      'function';

  const refreshDevices = useCallback(async () => {
    try {
      const inputs = await navigator.mediaDevices?.enumerateDevices();
      setDevices(inputs?.filter(item => item.kind === 'audioinput') ?? []);
    } catch {
      // A restricted device list must not prevent default-input capture.
    }
  }, []);

  const stop = useCallback(() => {
    request.current?.abort();
    request.current = undefined;
    capture.current?.dispose();
    capture.current = undefined;
    history.current = [];
    setStatus('idle');
    setFrequency(null);
    setLevel(0);
    setClipping(false);
  }, []);

  const start = async (id = deviceId) => {
    if (!supported) return;
    stop();
    setDeviceId(id);
    setError('');
    setStatus('connecting');
    const pending = new AbortController();
    request.current = pending;
    try {
      const input = await openTunerCapture(id, pending.signal, () => {
        if (pending.signal.aborted) return;
        stop();
        setError(
          'Аудиовход отключён. Подключите устройство и включите тюнер снова.',
        );
      });
      if (pending.signal.aborted) {
        input.dispose();
        return;
      }
      capture.current = input;
      setDeviceId(input.deviceId);
      setChannels(input.channels);
      setChannel(0);
      setStatus('listening');
      void refreshDevices();
    } catch (cause) {
      if (pending.signal.aborted) return;
      stop();
      setError(errorMessage(cause));
    }
  };

  useEffect(() => {
    void refreshDevices();
    navigator.mediaDevices?.addEventListener?.('devicechange', refreshDevices);
    return () => {
      navigator.mediaDevices?.removeEventListener?.(
        'devicechange',
        refreshDevices,
      );
      request.current?.abort();
      capture.current?.dispose();
    };
  }, [refreshDevices]);

  useEffect(() => {
    if (status !== 'listening') return;
    const timer = window.setInterval(() => {
      const input = capture.current;
      if (!input) return;
      const samples = input.read();
      let energy = 0;
      let peak = 0;
      samples.forEach(value => {
        energy += value * value;
        peak = Math.max(peak, Math.abs(value));
      });
      setLevel(Math.min(1, Math.sqrt(energy / samples.length) * 5));
      setClipping(peak >= 0.98);
      const detected = detectPitch(samples, input.sampleRate);
      if (detected === null) {
        history.current = [];
        setFrequency(null);
        return;
      }
      if (
        history.current.length &&
        Math.abs(centsBetween(detected, history.current[0])) > 80
      )
        history.current = [];
      history.current = [...history.current.slice(-2), detected];
      const sorted = [...history.current].sort((a, b) => a - b);
      setFrequency(sorted[Math.floor(sorted.length / 2)]);
    }, 80);
    return () => window.clearInterval(timer);
  }, [status]);

  return {
    supported,
    status,
    devices,
    deviceId,
    channel,
    channels,
    frequency,
    level,
    clipping,
    error,
    start,
    stop,
    selectDevice(id: string) {
      setDeviceId(id);
      if (status !== 'idle') void start(id);
    },
    selectChannel(value: number) {
      capture.current?.setChannel(value);
      setChannel(value);
      history.current = [];
      setFrequency(null);
    },
  };
};
