import { useEffect } from 'react';
import { useSelector } from 'react-redux';

import { updateInstrumentEffects } from 'app/services/SynthesizerService';

import { selectEffects } from './selectors';
import { useEffectsSlice } from './slice';

export const useEffects = () => {
  useEffectsSlice();
  const { instruments } = useSelector(selectEffects);
  useEffect(() => updateInstrumentEffects(instruments), [instruments]);
};
