import styled from 'styled-components';

import { NoiseGateSettings } from 'app/services/GuitarInputService/noiseGateSettings';

export const NoiseGateControls = ({
  settings,
  onChange,
}: {
  settings: NoiseGateSettings;
  onChange: (value: NoiseGateSettings) => void;
}) => (
  <Controls aria-label="Шумоподавление аудиовхода">
    <legend>
      <Toggle>
        <input
          type="checkbox"
          aria-label="Шумоподавление входа"
          checked={settings.enabled}
          onChange={event =>
            onChange({ ...settings, enabled: event.target.checked })
          }
        />
        Шумоподавление (гейт)
      </Toggle>
    </legend>
    <Fields>
      <label>
        Порог: {settings.threshold} дБFS
        <input
          type="range"
          aria-label="Порог шумоподавления"
          min={-80}
          max={-10}
          step={1}
          data-instrument-control="true"
          disabled={!settings.enabled}
          value={settings.threshold}
          aria-valuetext={`${settings.threshold} дБFS`}
          onChange={event =>
            onChange({ ...settings, threshold: Number(event.target.value) })
          }
        />
      </label>
      <label>
        Затухание: {settings.release} мс
        <input
          type="range"
          aria-label="Затухание шумоподавления"
          min={20}
          max={1000}
          step={10}
          data-instrument-control="true"
          disabled={!settings.enabled}
          value={settings.release}
          aria-valuetext={`${settings.release} мс`}
          onChange={event =>
            onChange({ ...settings, release: Number(event.target.value) })
          }
        />
      </label>
    </Fields>
    <p>
      Приглушает фон в паузах между нотами до перегруза и остальных эффектов.
      Поднимайте порог до исчезновения шума: слишком высокий порог обрезает
      тихие ноты. Затухание делает закрытие плавным. Исходная запись сохраняется
      без гейта.
    </p>
  </Controls>
);

const Controls = styled.fieldset`
  min-width: 0;
  margin: 12px 0;
  padding: 10px 12px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 8px;
  font-size: 12px;
  legend {
    padding: 0 6px;
  }
  p {
    color: ${p => p.theme.textSecondary};
    line-height: 1.5;
    margin-bottom: 0;
  }
  input[type='range'] {
    width: 100%;
  }
`;
const Toggle = styled.label`
  display: inline-flex !important;
  flex-direction: row !important;
  align-items: center;
  gap: 8px;
  margin: 0 !important;
`;
const Fields = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  label {
    display: flex;
    flex-direction: column;
    flex: 1 1 180px;
    min-width: 0;
    gap: 6px;
  }
`;
