import type { useGuitarInput } from 'app/services/GuitarInputService/useGuitarInput';

export const InputSoundControls = ({
  guitar,
}: {
  guitar: Pick<
    ReturnType<typeof useGuitarInput>,
    'inputSound' | 'inputPolyphonic' | 'setInputSound' | 'setInputPolyphonic'
  >;
}) => (
  <div>
    <label>
      Звук аудиовхода
      <select
        aria-label="Звук аудиовхода"
        value={guitar.inputSound ?? 'effects'}
        onChange={event =>
          guitar.setInputSound(event.target.value as 'effects' | 'instrument')
        }
      >
        <option value="effects">Исходный звук с эффектами</option>
        <option value="instrument">Выбранный тембр приложения</option>
      </select>
    </label>
    {guitar.inputSound === 'instrument' && (
      <>
        <label>
          Игра тембром
          <select
            aria-label="Распознавание для выбранного тембра"
            value={guitar.inputPolyphonic ? 'poly' : 'mono'}
            onChange={event =>
              guitar.setInputPolyphonic(event.target.value === 'poly')
            }
          >
            <option value="mono">Одна нота: быстрее</option>
            <option value="poly">Ноты и аккорды</option>
          </select>
        </label>
        <p>
          Выберите пианино или другой тембр в верхней панели и включите живой
          звук. Играть можно без записи. Громкость и эффекты берутся у
          выбранного тембра; исходный звук входа не слышен.
        </p>
        <p>
          Распознавание добавляет задержку. Одиночные чистые ноты откликаются
          быстрее; аккорды требуют больше времени и могут распознаваться с
          ошибками. Используйте наушники, чтобы звук приложения не попадал
          обратно в микрофон.
        </p>
      </>
    )}
  </div>
);
