import { useLayoutEffect, useRef, useState } from 'react';

import { KeyboardTrack } from 'app/services/PlayAlongService/keyboardLayout';

type KeyBox = { left: number; top: number; width: number; height: number };
type Geometry = { distance: number; keys: Record<string, KeyBox> };

export const useKeyboardGeometry = (rows: KeyboardTrack[]) => {
  const frame = useRef<HTMLDivElement>(null);
  const board = useRef<HTMLDivElement>(null);
  const [geometry, setGeometry] = useState<Geometry>({ distance: 0, keys: {} });

  useLayoutEffect(() => {
    const origin = frame.current;
    const keyboard = board.current;
    if (!origin || !keyboard) return;
    const measure = () => {
      const bounds = origin.getBoundingClientRect();
      const distance = keyboard.getBoundingClientRect().top - bounds.top;
      const keys: Geometry['keys'] = {};
      keyboard
        .querySelectorAll<HTMLButtonElement>('[data-key-id]')
        .forEach(key => {
          const row = key.offsetParent;
          if (row) {
            // Hit effects transform keys. Measure their layout, so a resize or
            // toolbar scroll during a bounce cannot move falling-note targets.
            const rowBounds = row.getBoundingClientRect();
            const style = getComputedStyle(key);
            keys[key.dataset.keyId!] = {
              left: rowBounds.left - bounds.left + parseFloat(style.left),
              top: rowBounds.top - bounds.top + parseFloat(style.top),
              width: parseFloat(style.width),
              height: parseFloat(style.height),
            };
            return;
          }
          const box = key.getBoundingClientRect();
          keys[key.dataset.keyId!] = {
            left: box.left - bounds.left,
            top: box.top - bounds.top,
            width: box.width,
            height: box.height,
          };
        });
      setGeometry(previous =>
        previous.distance === distance &&
        Object.keys(previous.keys).length === Object.keys(keys).length &&
        Object.entries(keys).every(([id, box]) =>
          (['left', 'top', 'width', 'height'] as const).every(
            field => previous.keys[id]?.[field] === box[field],
          ),
        )
          ? previous
          : { distance, keys },
      );
    };
    measure();
    const observer =
      typeof ResizeObserver === 'undefined'
        ? undefined
        : new ResizeObserver(measure);
    observer?.observe(origin);
    observer?.observe(keyboard);
    window.addEventListener('resize', measure);
    window.addEventListener('scroll', measure, true);
    return () => {
      observer?.disconnect();
      window.removeEventListener('resize', measure);
      window.removeEventListener('scroll', measure, true);
    };
  }, [rows]);

  return { frame, board, ...geometry };
};
