import { useDispatch, useSelector } from 'react-redux';
import styled from 'styled-components';

import { HeaderIconButton } from 'app/components/HeaderIconControl';

import { themeActions } from 'styles/theme/slice';
import { selectTheme } from 'styles/theme/slice/selectors';

export const ThemeSwitch = () => {
  const dispatch = useDispatch();
  const theme = useSelector(selectTheme);
  return (
    <ThemeButton
      type="button"
      aria-label="Переключить тему"
      title={`Переключить тему: сейчас ${
        theme.key === 'dark' ? 'тёмная' : 'светлая'
      }`}
      aria-pressed={theme.key === 'dark'}
      onClick={() => dispatch(themeActions.switchTheme())}
    >
      <ThemeSymbol aria-hidden="true" />
    </ThemeButton>
  );
};

const ThemeButton = styled(HeaderIconButton)``;

const ThemeSymbol = styled.span`
  width: 22px;
  height: 22px;
  border: 1.5px solid currentColor;
  border-radius: 50%;
  overflow: hidden;
  &::after {
    content: '';
    display: block;
    width: 50%;
    height: 100%;
    background: currentColor;
  }
`;
