import { useCallback, useEffect, useId, useRef, useState } from 'react';
import { batch, useDispatch } from 'react-redux';

import { Note, notesActions } from 'app/services/NotesService';
import { Timbre } from 'app/services/SynthesizerService';

export const useChordPreview = (timbre: Timbre) => {
  const dispatch = useDispatch();
  const source = `chord-preview-${useId()}`;
  const active = useRef<{ notes: Note[]; timbre: Timbre; timer: number }>();
  const [isPlaying, setPlaying] = useState(false);
  const [activeStep, setActiveStep] = useState<number | null>(null);

  const release = useCallback(() => {
    const played = active.current;
    if (!played) return;
    active.current = undefined;
    window.clearTimeout(played.timer);
    batch(() =>
      played.notes.forEach(note => {
        dispatch(
          notesActions.muteNote({ note, timbre: played.timbre, source }),
        );
      }),
    );
  }, [dispatch, source]);

  const stop = useCallback(() => {
    release();
    setPlaying(false);
    setActiveStep(null);
  }, [release]);

  const playSequence = useCallback(
    (steps: Note[][], stepDuration = 1000) => {
      stop();
      if (!steps.length) return;
      const advance = (index: number) => {
        release();
        if (index === steps.length) {
          stop();
          return;
        }
        const notes = Array.from(new Set(steps[index]));
        batch(() =>
          notes.forEach(note => {
            dispatch(notesActions.playNote({ note, timbre, source }));
          }),
        );
        active.current = {
          notes,
          timbre,
          timer: window.setTimeout(() => advance(index + 1), stepDuration),
        };
        setActiveStep(index);
        setPlaying(true);
      };
      advance(0);
    },
    [dispatch, release, source, stop, timbre],
  );

  const play = useCallback(
    (notes: Note[]) => {
      stop();
      batch(() =>
        notes.forEach(note => {
          dispatch(notesActions.playNote({ note, timbre, source }));
        }),
      );
      active.current = { notes, timbre, timer: window.setTimeout(stop, 1400) };
      setPlaying(true);
    },
    [dispatch, source, stop, timbre],
  );

  useEffect(() => {
    const hide = () => {
      if (document.hidden) stop();
    };
    window.addEventListener('blur', stop);
    document.addEventListener('visibilitychange', hide);
    return () => {
      stop();
      window.removeEventListener('blur', stop);
      document.removeEventListener('visibilitychange', hide);
    };
  }, [stop, timbre]);

  return { play, playSequence, stop, isPlaying, activeStep };
};

export type ChordPlayback = ReturnType<typeof useChordPreview>;
