import { InstrumentEffects } from 'app/services/EffectsService/settings';

import { microphoneTimeoutMessage, waitForAudioInput } from './connection';
import {
  InputLatency,
  LiveMonitor,
  createLiveMonitor,
  readInputLatency,
} from './liveMonitor';
import {
  NoiseGateSettings,
  defaultNoiseGate,
  normalizeNoiseGate,
} from './noiseGateSettings';

export type GuitarTake = {
  samples: Float32Array;
  sampleRate: number;
  startedAt: number;
  version: number;
};

export type GuitarSamples = Pick<
  GuitarTake,
  'samples' | 'sampleRate' | 'startedAt'
>;

export type GuitarCapture = {
  audioContext: AudioContext;
  deviceId: string;
  channels: number;
  setChannel(channel: number): void;
  level(): { rms: number; peak: number };
  startTake(version: number, onSamples?: (chunk: GuitarSamples) => void): void;
  setSampleListener(listener?: (chunk: GuitarSamples) => void): void;
  stopTake(): Promise<GuitarTake | undefined>;
  setMonitoring(settings?: InstrumentEffects): Promise<void>;
  setNoiseGate(settings: NoiseGateSettings): void;
  outputLevel(): { rms: number; peak: number };
  latency(): InputLatency;
  canSelectOutput: boolean;
  setOutputDevice(deviceId: string): Promise<void>;
  dispose(): void;
};

export const openGuitarCapture = async (
  deviceId: string,
  signal: AbortSignal,
  onEnded: () => void,
  onStatus: (message: string) => void = () => {},
): Promise<GuitarCapture> => {
  const Context = window.AudioContext || (window as any).webkitAudioContext;
  const contextOptions: AudioContextOptions & { renderSizeHint: number } = {
    latencyHint: 'interactive',
    renderSizeHint: 128,
  };
  const context: AudioContext = new Context(contextOptions);
  let stream: MediaStream | undefined;
  let disposed = false;
  let source: MediaStreamAudioSourceNode | undefined;
  let splitter: ChannelSplitterNode | undefined;
  let analyser: AnalyserNode | undefined;
  let worklet: AudioWorkletNode | undefined;
  let selectedInput: GainNode | undefined;
  let monitor: LiveMonitor | undefined;
  let noiseGate = defaultNoiseGate;
  let sampleListener: ((chunk: GuitarSamples) => void) | undefined;
  let take:
    | {
        version: number;
        startedAt: number;
        chunks: Float32Array[];
        length: number;
        onSamples?: (chunk: GuitarSamples) => void;
      }
    | undefined;
  let stopping:
    | {
        resolve: (take: GuitarTake | undefined) => void;
        reject: (error: Error) => void;
        timer: ReturnType<typeof setTimeout>;
      }
    | undefined;
  const abortError = () => new DOMException('Capture cancelled', 'AbortError');
  const dispose = () => {
    if (disposed) return;
    disposed = true;
    sampleListener = undefined;
    monitor?.dispose();
    monitor = undefined;
    signal.removeEventListener('abort', dispose);
    stream?.getTracks().forEach(track => {
      track.removeEventListener('ended', onEnded);
      track.stop();
    });
    source?.disconnect();
    splitter?.disconnect();
    selectedInput?.disconnect();
    analyser?.disconnect();
    worklet?.disconnect();
    if (worklet) {
      worklet.port.onmessage = null;
      worklet.port.close();
    }
    if (stopping) {
      clearTimeout(stopping.timer);
      stopping.reject(abortError());
      stopping = undefined;
    }
    take = undefined;
    context.close().catch(() => {});
  };
  signal.addEventListener('abort', dispose, { once: true });
  if (signal.aborted) {
    dispose();
    throw abortError();
  }
  try {
    if (!context.audioWorklet || typeof AudioWorkletNode === 'undefined')
      throw new Error('AudioWorklet is unavailable');
    // Call resume in the initiating click, before awaiting browser permission.
    // Observe rejection immediately, but wait for resume only after wiring the
    // input. Some browsers need an active capture graph to start audio.
    void context.resume().catch(() => {});
    onStatus('Ожидаем доступ к микрофону. Разрешите его в запросе браузера.');
    const media = navigator.mediaDevices
      .getUserMedia({
        video: false,
        audio: {
          ...(deviceId ? { deviceId: { exact: deviceId } } : {}),
          channelCount: { ideal: 2 },
          echoCancellation: false,
          noiseSuppression: false,
          autoGainControl: false,
          latency: { ideal: 0 },
          sampleRate: { ideal: context.sampleRate },
        },
      })
      .then(value => {
        if (disposed) {
          value.getTracks().forEach(track => track.stop());
          throw abortError();
        }
        stream = value;
        return value;
      });
    const input = await waitForAudioInput(
      media,
      signal,
      microphoneTimeoutMessage,
      30000,
    );
    onStatus('Подготавливаем обработку аудиовхода…');
    await waitForAudioInput(
      context.audioWorklet.addModule(
        `${process.env.PUBLIC_URL}/guitar-capture.worklet.js?v=3`,
      ),
      signal,
      'Не удалось загрузить обработку аудиовхода. Проверьте соединение и обновите страницу.',
    );
    if (disposed) throw abortError();
    const track = input.getAudioTracks()[0];
    if (!track || track.readyState === 'ended')
      throw new Error('Audio input ended');
    track.addEventListener('ended', onEnded);
    const settings = track.getSettings() as MediaTrackSettings & {
      channelCount?: number;
    };
    const channels = Math.max(1, Math.min(32, settings.channelCount ?? 1));
    source = context.createMediaStreamSource(input);
    splitter = context.createChannelSplitter(channels);
    selectedInput = context.createGain();
    analyser = context.createAnalyser();
    analyser.fftSize = 1024;
    worklet = new AudioWorkletNode(context, 'qwertophone-guitar-capture', {
      numberOfInputs: 1,
      numberOfOutputs: 1,
      outputChannelCount: [1],
    });
    source.connect(splitter);
    splitter.connect(selectedInput, 0);
    selectedInput.connect(analyser);
    selectedInput.connect(worklet);
    // The worklet leaves output buffers at zero, so capture never feeds back.
    worklet.connect(context.destination);
    onStatus('Запускаем аудиодвижок…');
    // Retry after permission is granted and the capture graph is connected.
    await waitForAudioInput(
      context.state === 'running' ? Promise.resolve() : context.resume(),
      signal,
      'Браузер не запустил аудиодвижок. Повторите подключение. Если это не помогает, откройте Qwertophone в отдельном браузере.',
    );
    if (disposed) throw abortError();
    const epoch = Date.now() - context.currentTime * 1000;
    worklet.port.onmessage = ({ data }) => {
      if (data.type === 'live-samples') {
        sampleListener?.({
          samples: data.samples,
          sampleRate: context.sampleRate,
          startedAt: epoch + (data.frame / context.sampleRate) * 1000,
        });
        return;
      }
      if (!take) return;
      if (data.type === 'start')
        take.startedAt = epoch + (data.frame / context.sampleRate) * 1000;
      if (data.type === 'samples') {
        take.chunks.push(data.samples);
        take.length += data.samples.length;
        take.onSamples?.({
          samples: data.samples,
          sampleRate: context.sampleRate,
          startedAt: take.startedAt,
        });
      }
      if (data.type === 'stopped' && stopping) {
        const samples = new Float32Array(take.length);
        let offset = 0;
        take.chunks.forEach(chunk => {
          samples.set(chunk, offset);
          offset += chunk.length;
        });
        clearTimeout(stopping.timer);
        stopping.resolve({
          version: take.version,
          startedAt: take.startedAt,
          samples,
          sampleRate: context.sampleRate,
        });
        stopping = undefined;
        take = undefined;
      }
    };
    const levelData = new Float32Array(analyser.fftSize);
    const outputContext = context as AudioContext & {
      setSinkId?: (id: string) => Promise<void>;
    };
    return {
      audioContext: context,
      deviceId: settings.deviceId ?? deviceId,
      channels,
      setChannel(channel) {
        if (
          take ||
          !Number.isInteger(channel) ||
          channel < 0 ||
          channel >= channels
        )
          return;
        splitter!.disconnect();
        splitter!.connect(selectedInput!, channel);
      },
      level() {
        analyser!.getFloatTimeDomainData(levelData);
        let energy = 0;
        let peak = 0;
        for (let i = 0; i < levelData.length; i++) {
          energy += levelData[i] ** 2;
          peak = Math.max(peak, Math.abs(levelData[i]));
        }
        return { rms: Math.sqrt(energy / levelData.length), peak };
      },
      startTake(version, onSamples) {
        if (disposed || take) return;
        take = {
          version,
          startedAt: Date.now(),
          chunks: [],
          length: 0,
          onSamples,
        };
        worklet!.port.postMessage({ recording: true });
      },
      setSampleListener(listener) {
        if (disposed) return;
        sampleListener = listener;
        worklet!.port.postMessage({ listening: !!listener });
      },
      setMonitoring(value) {
        if (disposed) return Promise.resolve();
        if (!value) {
          monitor?.dispose();
          monitor = undefined;
        } else if (monitor) monitor.update(value);
        else
          monitor = createLiveMonitor(
            context,
            selectedInput!,
            value,
            noiseGate,
          );
        return value && context.state === 'suspended'
          ? context.resume()
          : Promise.resolve();
      },
      setNoiseGate(value) {
        if (disposed) return;
        noiseGate = normalizeNoiseGate(value);
        monitor?.updateNoiseGate(noiseGate);
      },
      outputLevel: () => monitor?.level() ?? { rms: 0, peak: 0 },
      latency: () => readInputLatency(context, track),
      canSelectOutput: typeof outputContext.setSinkId === 'function',
      setOutputDevice(id) {
        if (!outputContext.setSinkId)
          return Promise.reject(new Error('Output selection unavailable'));
        return outputContext.setSinkId(id);
      },
      stopTake() {
        if (!take) return Promise.resolve(undefined);
        return new Promise((resolve, reject) => {
          stopping = {
            resolve,
            reject,
            timer: setTimeout(() => {
              stopping = undefined;
              take = undefined;
              reject(new Error('Audio capture did not finish'));
            }, 1500),
          };
          worklet!.port.postMessage({ recording: false });
        });
      },
      dispose,
    };
  } catch (error) {
    dispose();
    throw error;
  }
};
